using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class ModelFolderSurvey {public static string Main(){string root="Assets/Afrer_Seconds/05.Model/";var floors=new[]{"B5","B4","B3","B2","B1","1F"};var scenes=AssetDatabase.FindAssets("t:Scene",new[]{"Assets/Afrer_Seconds/01.Scenes/Stage"}).Select(AssetDatabase.GUIDToAssetPath).ToArray();var deps=scenes.ToDictionary(s=>s,s=>AssetDatabase.GetDependencies(s,true));var assets=AssetDatabase.GetAllAssetPaths().Where(p=>(p.StartsWith(root)||p.StartsWith("Assets/Afrer_Seconds/03.Art/Candidates/VARCO/"))&&!AssetDatabase.IsValidFolder(p)).Select(p=>new{path=p,guid=AssetDatabase.AssetPathToGUID(p),type=AssetDatabase.GetMainAssetTypeAtPath(p)?.FullName,floors=scenes.Where(s=>deps[s].Contains(p)).Select(s=>floors.FirstOrDefault(f=>Path.GetFileName(s).Contains("_"+f+"_"))).Where(f=>f!=null).ToArray()}).ToArray();string r=Path.GetFullPath(Path.Combine(Directory.GetParent(Application.dataPath).FullName,"../../tmp/ModelFolderCleanup_20261103"));var open=Enumerable.Range(0,SceneManager.sceneCount).Select(i=>SceneManager.GetSceneAt(i)).Select(s=>new{s.path,s.isDirty}).ToArray();File.WriteAllText(r+"/asset_inventory.json",JsonConvert.SerializeObject(new{assets,scenes,open,playing=EditorApplication.isPlaying},Formatting.Indented));return JsonConvert.SerializeObject(new{assets=assets.Length,scenes,open,playing=EditorApplication.isPlaying});}}

